def is_valid_business_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or local[0] == '.' or local[-1] == '.' or '..' in local:
        return False
    if not _LOCAL_RE.match(local):
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    if not all(_LABEL_RE.match(label) for label in labels):
        return False
    return labels[-1] in {'com', 'org', 'net', 'io'}

