def render_row_left(cells, widths):
    i = 0
    out = []
    while i < len(cells):
        cell = cells[i]
        width = widths[i]
        if len(cell) < width:
            cell = cell + (' ' * (width - len(cell)))
        out.append(cell)
        i += 1
    return ' | '.join(out)

def sentence_case_multi(text):
    import re
    def fix(frag):
        low = frag.lower()
        m = re.search(r'[a-z]', low)
        if not m:
            return low
        i = m.start()
        return low[:i] + low[i].upper() + low[i + 1:]
    return '. '.join(fix(p) for p in text.split('. '))

def nth_prime(n):
    primes = []
    candidate = 2
    while len(primes) < n:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1
    return primes[-1]

def nested_group_counts(pairs):
    from collections import defaultdict
    counts = defaultdict(lambda: defaultdict(int))
    for group, item in pairs:
        counts[group][item] += 1
    return {g: dict(inner) for g, inner in counts.items()}

