def is_valid_snake_case(s):
    return bool(re.fullmatch(r'[a-z][a-z0-9]*(_[a-z0-9]+)*', s))

def is_snake_case(s):
    if not s:
        return False
    prev_underscore = True
    for ch in s:
        if ch == '_':
            if prev_underscore:
                return False
            prev_underscore = True
        elif ch.isdigit() or (ch.isalpha() and ch.islower()):
            prev_underscore = False
        else:
            return False
    return not prev_underscore

