def sliding_window_sums(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    window_sum = sum(lst[:k])
    sums = [window_sum]
    for i in range(k, n):
        window_sum += lst[i] - lst[i - k]
        sums.append(window_sum)
    return sums

